import{_ as t,o as i,c as a,a2 as r}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse(`{"title":"Risks and Kill Criteria","description":"Hearth's main risks, global pause conditions, phase Kill Criteria, project-level Kill Criteria, and the things that should not be Killed.","frontmatter":{"title":"Risks and Kill Criteria","description":"Hearth's main risks, global pause conditions, phase Kill Criteria, project-level Kill Criteria, and the things that should not be Killed.","outline":[2,3]},"headers":[],"relativePath":"en/reference/risks.md","filePath":"en/reference/risks.md","lastUpdated":1793797632000}`),l={name:"en/reference/risks.md"};function n(o,e,s,d,c,u){return i(),a("div",null,[...e[0]||(e[0]=[r('<p class="eyebrow">RISKS</p><h1 id="risks-and-kill-criteria" tabindex="-1">Risks and Kill Criteria <a class="header-anchor" href="#risks-and-kill-criteria" aria-label="Permalink to &quot;Risks and Kill Criteria&quot;">​</a></h1><p class="lead">When to pause, roll back, or stop a project is a harder and more important decision than “keep going.”</p><h2 id="risks-and-kill-criteria-1" tabindex="-1">Risks and Kill Criteria <a class="header-anchor" href="#risks-and-kill-criteria-1" aria-label="Permalink to &quot;Risks and Kill Criteria&quot;">​</a></h2><h3 id="key-risks" tabindex="-1">Key Risks <a class="header-anchor" href="#key-risks" aria-label="Permalink to &quot;Key Risks&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Risk</th><th>Early Signal</th><th>Mitigation</th></tr></thead><tbody><tr><td>Scope creep</td><td>New Executors added at every stage while the core loop is not stable</td><td>Control scope with Task sets and stage gates</td></tr><tr><td>Insufficient reliability</td><td>Tasks lost after crashes, duplicate sends</td><td>Single writer, outbox, lease, fault injection</td></tr><tr><td>Security incident</td><td>Privilege escalation, secret leakage, successful prompt injection</td><td>Sandbox, Broker, approvals, red teaming</td></tr><tr><td>Runaway Token cost</td><td>Per-Task cost is high and human minutes are not decreasing</td><td>Context Compiler, routing, caching, hard budgets</td></tr><tr><td>External Agent dependency</td><td>Version changes cause many Task failures</td><td>Adapters, version pinning, fallback to Native/manual</td></tr><tr><td>Maintenance burden</td><td>Large amounts of time each week fixing dependencies and channels</td><td>Do not build low-level components in-house, reduce connectors, automated upgrade tests</td></tr><tr><td>Notification fatigue</td><td>Users disable notifications or ignore approvals</td><td>Attention budget, aggregation, silence, default actions</td></tr><tr><td>Memory errors</td><td>Repeatedly citing outdated or incorrect facts</td><td>Provenance, confidence, conflicts, forgetting, user correction</td></tr><tr><td>Self-evolution drift</td><td>Skills become more complex with use, permissions increase</td><td>Evaluation, shadow, canary, permission intersection, rollback</td></tr><tr><td>Multi-device complexity</td><td>Sync conflicts, duplicate execution</td><td>Single writer, lease, fencing, offline queue</td></tr><tr><td>Product feels like a wrapper</td><td>No independent value after removing Codex</td><td>Control Plane, memory, approvals, recovery, evaluation</td></tr><tr><td>Platform limits</td><td>Browser login, CAPTCHA, API changes</td><td>Manual takeover, official API first, fallback</td></tr><tr><td>Declining user trust</td><td>Users do not understand why it did this or cannot undo it</td><td>Explainable state, Artifact, Receipt, kill switch</td></tr><tr><td>Unsustainable time investment</td><td>Maintenance exceeds available time</td><td>Narrow scope, delay non-core capabilities, automated testing</td></tr></tbody></table><h3 id="global-pause-conditions" tabindex="-1">Global Pause Conditions <a class="header-anchor" href="#global-pause-conditions" aria-label="Permalink to &quot;Global Pause Conditions&quot;">​</a></h3><p>When the following occur, pause new features and prioritize fixes:</p><ul><li>High-risk actions overstep permissions;</li><li>Secrets or sensitive data leak;</li><li>Fault injection produces duplicate external side effects;</li><li>Crash recovery rate is below 95%;</li><li>Users cannot revoke devices, connections, or skills;</li><li>Critical memory cannot be forgotten;</li><li>Task status is inconsistent with the source of truth;</li><li>External side effects cannot be reconciled.</li></ul><h3 id="phase-kill-criteria" tabindex="-1">Phase Kill Criteria <a class="header-anchor" href="#phase-kill-criteria" aria-label="Permalink to &quot;Phase Kill Criteria&quot;">​</a></h3><p><strong>Phase 1:</strong></p><ul><li>Cannot define 10 real tasks with acceptance criteria;</li><li>Cannot explain the difference between Hearth and using existing tools directly;</li><li>No threat model or basic security boundary;</li><li>The prototype cannot let users complete the main path without instructions;</li><li>After meeting the MVP threshold, still cannot complete 8 real tasks;</li><li>Duplicate external actions cannot be eliminated;</li><li>Recovery depends on manual state reconstruction;</li><li>Task status can only be inferred from chat history;</li><li>The backend is available, but the browser cannot complete creation, viewing, approval, recovery, and artifact retrieval.</li></ul><p><strong>Phase 2:</strong></p><ul><li>The email or calendar loop requires users to frequently rebuild background information;</li><li>Source permissions cannot be minimized;</li><li>Document, table, or web results cannot be verified;</li><li>Manual time for common tasks has not decreased;</li><li>Data cross-talk between accounts or projects;</li><li>External writes may run twice or cannot be checked.</li></ul><p><strong>Phase 3:</strong></p><ul><li>Desktop task success rate is low and cannot be taken over;</li><li>Cannot prove operations did not overstep permissions;</li><li>The desktop state cannot be recovered;</li><li>Every desktop task requires heavy manual intervention;</li><li>Failure tends to leave a half-finished high-risk state.</li></ul><p><strong>Phase 4:</strong></p><ul><li>Proactive tasks create notification fatigue;</li><li>Users cannot predict when they will be interrupted;</li><li>Mobile approvals can be reused or overstep permissions;</li><li>Background tasks cannot be stopped or budgets run out of control;</li><li>High-risk actions bypass approval because they are proactive.</li></ul><p><strong>Phase 5:</strong></p><ul><li>Memory errors cause continuous rework;</li><li>Forgetting cannot propagate to summaries, indexes, and related content;</li><li>Method evaluation can be manipulated by cherry-picked samples;</li><li>New methods expand permissions or cause security regressions;</li><li>The old version cannot be restored.</li></ul><p><strong>Phase 6:</strong></p><ul><li>Multi-device duplicate execution or state split;</li><li>A lost device cannot be revoked promptly;</li><li>After migration, tasks, memory, or artifacts are inconsistent;</li><li>Long-term operation maintenance cost exceeds product value;</li><li>Users cannot back up, restore, or leave independently.</li></ul><h3 id="project-level-kill-criteria" tabindex="-1">Project-Level Kill Criteria <a class="header-anchor" href="#project-level-kill-criteria" aria-label="Permalink to &quot;Project-Level Kill Criteria&quot;">​</a></h3><p>In the following cases, consider narrowing the product rather than continuing to add features:</p><ul><li>After Phase 2, there are still no stable 10 real daily tasks;</li><li>Human minutes have not substantially decreased; users are just “watching the Agent work”;</li><li>Maintenance cost continues to exceed available time with no downward trend;</li><li>Simply switching models can replace most of Hearth&#39;s value;</li><li>Security boundaries cannot reach an acceptable level;</li><li>Users are unwilling to hand over real email, files, or calendars to it;</li><li>Self-evolution continuously produces unexplainable drift;</li><li>Multi-device complexity swallows the single-device experience.</li></ul><h3 id="what-should-not-be-killed" tabindex="-1">What Should Not Be Killed <a class="header-anchor" href="#what-should-not-be-killed" aria-label="Permalink to &quot;What Should Not Be Killed&quot;">​</a></h3><ul><li>Event Log and recoverability;</li><li>Approvals, idempotency, and Receipt;</li><li>Evaluation and failure samples;</li><li>Memory forgetting and user correction;</li><li>Task cards and low-interruption experience;</li><li>Manual takeover;</li><li>Security boundaries and kill switch.</li></ul><p>These are the product&#39;s foundation, not features that can be deleted when “rushing progress.”</p><hr>',29)])])}const m=t(l,[["render",n]]);export{p as __pageData,m as default};
